import{_ as l,a0 as p,w as d,s as o,ao as h,I as n,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何設置 Linux 系統的密碼策略 | LCTT x X-CMD","titleTemplate":false,"description":"如何設置 Linux 系統的密碼策略 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何設置 Linux 系統的密碼策略 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何設置 Linux 系統的密碼策略 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20160301 How To Set Password Policies In Linux","title":"如何設置 Linux 系統的密碼策略","tag":"201904","desc":""},"relativePath":"201904/20160301 How To Set Password Policies In Linux.md","filePath":"[post].md"}'),r={name:"201904/20160301 How To Set Password Policies In Linux.md"};function c(g,s,k,u,b,f){const e=p("Link");return d(),o("div",null,[s[15]||(s[15]=h(`<h1 id="如何設置-linux-系統的密碼策略" tabindex="-1">如何設置 Linux 系統的密碼策略 <a class="header-anchor" href="#如何設置-linux-系統的密碼策略" aria-label="Permalink to “如何設置 Linux 系統的密碼策略”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/03/How-To-Set-Password-Policies-In-Linux-720x340.jpg" alt=""></p><p>雖然 Linux 的設計是安全的，但還是存在許多安全漏洞的風險，弱密碼就是其中之一。作為系統管理員，你必須為用户提供一個強密碼。因為大部分的系統漏洞就是由於弱密碼而引發的。本教程描述了在基於 DEB 系統的 Linux，比如 Debian、Ubuntu、Linux Mint 等和基於 RPM 系統的 Linux，比如 RHEL、CentOS、Scientific Linux 等的系統下設置像<strong>密碼長度</strong>、<strong>密碼複雜度</strong>、<strong>密碼有效期</strong>等密碼策略。</p><h3 id="在基於-deb-的系統中設置密碼長度" tabindex="-1">在基於 DEB 的系統中設置密碼長度 <a class="header-anchor" href="#在基於-deb-的系統中設置密碼長度" aria-label="Permalink to “在基於 DEB 的系統中設置密碼長度”">​</a></h3><p>默認情況下，所有的 Linux 操作系統要求用户<strong>密碼長度最少 6 個字符</strong>。我強烈建議不要低於這個限制。並且不要使用你的真實名稱、父母、配偶、孩子的名字，或者你的生日作為密碼。即便是一個黑客新手，也可以很快地破解這類密碼。一個好的密碼必須是至少 6 個字符，並且包含數字、大寫字母和特殊符號。</p><p>通常地，在基於 DEB 的操作系統中，密碼和身份認證相關的配置文件被存儲在 <code>/etc/pam.d/</code> 目錄中。</p><p>設置最小密碼長度，編輯 <code>/etc/pam.d/common-password</code> 文件；</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/pam.d/common-password</span></span></code></pre></div><p>找到下面這行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password [success=2 default=ignore] pam_unix.so obscure sha512</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2016/03/sk@sk-_003-2-1.jpg" alt=""></p><p>在末尾添加額外的文字：<code>minlen=8</code>。在這裏我設置的最小密碼長度為 <code>8</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password [success=2 default=ignore] pam_unix.so obscure sha512 minlen=8</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/03/sk@sk-_002-3-1.jpg" alt=""></p><p>保存並關閉該文件。這樣一來，用户現在不能設置小於 8 個字符的密碼。</p><h3 id="在基於-rpm-的系統中設置密碼長度" tabindex="-1">在基於 RPM 的系統中設置密碼長度 <a class="header-anchor" href="#在基於-rpm-的系統中設置密碼長度" aria-label="Permalink to “在基於 RPM 的系統中設置密碼長度”">​</a></h3><p><strong>在 RHEL、CentOS、Scientific Linux 7.x</strong> 系統中， 以 root 身份執行下面的命令來設置密碼長度。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># authconfig --passminlen=8 --update</span></span></code></pre></div><p>查看最小密碼長度，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep &quot;^minlen&quot; /etc/security/pwquality.conf</span></span></code></pre></div><p><strong>輸出樣例：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>minlen = 8</span></span></code></pre></div><p><strong>在 RHEL、CentOS、Scientific Linux 6.x</strong> 系統中，編輯 <code>/etc/pam.d/system-auth</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nano /etc/pam.d/system-auth</span></span></code></pre></div><p>找到下面這行並在該行末尾添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password requisite pam_cracklib.so try_first_pass retry=3 type= minlen=8</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/03/root@server_003-3.jpg" alt=""></p><p>如上設置中，最小密碼長度是 <code>8</code> 個字符。</p><h3 id="在基於-deb-的系統中設置密碼複雜度" tabindex="-1">在基於 DEB 的系統中設置密碼複雜度 <a class="header-anchor" href="#在基於-deb-的系統中設置密碼複雜度" aria-label="Permalink to “在基於 DEB 的系統中設置密碼複雜度”">​</a></h3><p>此設置會強制要求密碼中應該包含多少類型，比如大寫字母、小寫字母和其他字符。</p><p>首先，用下面命令安裝密碼質量檢測庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install libpam-pwquality</span></span></code></pre></div><p>之後，編輯 <code>/etc/pam.d/common-password</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/pam.d/common-password</span></span></code></pre></div><p>為了設置密碼中至少有一個<strong>大寫字母</strong>，則在下面這行的末尾添加文字 <code>ucredit=-1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password requisite pam_pwquality.so retry=3 ucredit=-1</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/03/sk@sk-_001-7.jpg" alt=""></p><p>設置密碼中至少有一個<strong>小寫字母</strong>，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password requisite pam_pwquality.so retry=3 dcredit=-1</span></span></code></pre></div><p>設置密碼中至少含有其他字符，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password requisite pam_pwquality.so retry=3 ocredit=-1</span></span></code></pre></div><p>正如你在上面樣例中看到的一樣，我們設置了密碼中至少含有一個大寫字母、一個小寫字母和一個特殊字符。你可以設置被最大允許的任意數量的大寫字母、小寫字母和特殊字符。</p><p>你還可以設置密碼中被允許的字符類的最大或最小數量。</p><p>下面的例子展示了設置一個新密碼中被要求的字符類的最小數量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password requisite pam_pwquality.so retry=3 minclass=2</span></span></code></pre></div><h3 id="在基於-rpm-的系統中設置密碼複雜度" tabindex="-1">在基於 RPM 的系統中設置密碼複雜度 <a class="header-anchor" href="#在基於-rpm-的系統中設置密碼複雜度" aria-label="Permalink to “在基於 RPM 的系統中設置密碼複雜度”">​</a></h3><p><strong>在 RHEL 7.x / CentOS 7.x / Scientific Linux 7.x 中：</strong></p><p>設置密碼中至少有一個小寫字母，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># authconfig --enablereqlower --update</span></span></code></pre></div><p>查看該設置，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep &quot;^lcredit&quot; /etc/security/pwquality.conf</span></span></code></pre></div><p><strong>輸出樣例：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lcredit = -1</span></span></code></pre></div><p>類似地，使用以下命令去設置密碼中至少有一個大寫字母：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># authconfig --enablerequpper --update</span></span></code></pre></div><p>查看該設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep &quot;^ucredit&quot; /etc/security/pwquality.conf</span></span></code></pre></div><p><strong>輸出樣例：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ucredit = -1</span></span></code></pre></div><p>設置密碼中至少有一個數字，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># authconfig --enablereqdigit --update</span></span></code></pre></div><p>查看該設置，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep &quot;^dcredit&quot; /etc/security/pwquality.conf</span></span></code></pre></div><p><strong>輸出樣例：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dcredit = -1</span></span></code></pre></div><p>設置密碼中至少含有一個其他字符，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># authconfig --enablereqother --update</span></span></code></pre></div><p>查看該設置，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># grep &quot;^ocredit&quot; /etc/security/pwquality.conf</span></span></code></pre></div><p><strong>輸出樣例：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ocredit = -1</span></span></code></pre></div><p>在 <strong>RHEL 6.x / CentOS 6.x / Scientific Linux 6.x systems</strong> 中，以 root 身份編輯 <code>/etc/pam.d/system-auth</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># nano /etc/pam.d/system-auth</span></span></code></pre></div><p>找到下面這行並且在該行末尾添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password requisite pam_cracklib.so try_first_pass retry=3 type= minlen=8 dcredit=-1 ucredit=-1 lcredit=-1 ocredit=-1</span></span></code></pre></div><p>如上設置中，密碼必須要至少包含 <code>8</code> 個字符。另外，密碼必須至少包含一個大寫字母、一個小寫字母、一個數字和一個其他字符。</p><h3 id="在基於-deb-的系統中設置密碼有效期" tabindex="-1">在基於 DEB 的系統中設置密碼有效期 <a class="header-anchor" href="#在基於-deb-的系統中設置密碼有效期" aria-label="Permalink to “在基於 DEB 的系統中設置密碼有效期”">​</a></h3><p>現在，我們將要設置下面的策略。</p><ol><li>密碼被使用的最長天數。</li><li>密碼更改允許的最小間隔天數。</li><li>密碼到期之前發出警告的天數。</li></ol><p>設置這些策略，編輯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/login.defs</span></span></code></pre></div><p>在你的每個需求後設置值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PASS_MAX_DAYS 100</span></span>
<span class="line"><span>PASS_MIN_DAYS 0</span></span>
<span class="line"><span>PASS_WARN_AGE 7</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/03/sk@sk-_002-8.jpg" alt=""></p><p>正如你在上面樣例中看到的一樣，用户應該每 <code>100</code> 天修改一次密碼，並且密碼到期之前的 <code>7</code> 天開始出現警告信息。</p><p>請注意，這些設置將會在新創建的用户中有效。</p><p>為已存在的用户設置修改密碼的最大間隔天數，你必須要運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -M &lt;days&gt; &lt;username&gt;</span></span></code></pre></div><p>設置修改密碼的最小間隔天數，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -m &lt;days&gt; &lt;username&gt;</span></span></code></pre></div><p>設置密碼到期之前的警告，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -W &lt;days&gt; &lt;username&gt;</span></span></code></pre></div><p>顯示已存在用户的密碼，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -l sk</span></span></code></pre></div><p>這裏，<strong>sk</strong> 是我的用户名。</p><p><strong>輸出樣例：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Last password change : Feb 24, 2017</span></span>
<span class="line"><span>Password expires : never</span></span>
<span class="line"><span>Password inactive : never</span></span>
<span class="line"><span>Account expires : never</span></span>
<span class="line"><span>Minimum number of days between password change : 0</span></span>
<span class="line"><span>Maximum number of days between password change : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires : 7</span></span></code></pre></div><p>正如你在上面看到的輸出一樣，該密碼是無限期的。</p><p>修改已存在用户的密碼有效期，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chage -E 24/06/2018 -m 5 -M 90 -I 10 -W 10 sk</span></span></code></pre></div><p>上面的命令將會設置用户 <code>sk</code> 的密碼期限是 <code>24/06/2018</code>。並且修改密碼的最小間隔時間為 <code>5</code> 天，最大間隔時間為 <code>90</code> 天。用户賬號將會在 <code>10</code> 天后被自動鎖定，而且在到期之前的 <code>10</code> 天前顯示警告信息。</p><h3 id="在基於-rpm-的系統中設置密碼效期" tabindex="-1">在基於 RPM 的系統中設置密碼效期 <a class="header-anchor" href="#在基於-rpm-的系統中設置密碼效期" aria-label="Permalink to “在基於 RPM 的系統中設置密碼效期”">​</a></h3><p>這點和基於 DEB 的系統是相同的。</p><h3 id="在基於-deb-的系統中禁止使用近期使用過的密碼" tabindex="-1">在基於 DEB 的系統中禁止使用近期使用過的密碼 <a class="header-anchor" href="#在基於-deb-的系統中禁止使用近期使用過的密碼" aria-label="Permalink to “在基於 DEB 的系統中禁止使用近期使用過的密碼”">​</a></h3><p>你可以限制用户去設置一個已經使用過的密碼。通俗的講，就是説用户不能再次使用相同的密碼。</p><p>為設置這一點，編輯 <code>/etc/pam.d/common-password</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/pam.d/common-password</span></span></code></pre></div><p>找到下面這行並且在末尾添加文字 <code>remember=5</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password        [success=2 default=ignore]      pam_unix.so obscure use_authtok try_first_pass sha512 remember=5</span></span></code></pre></div><p>上面的策略將會阻止用户去使用最近使用過的 5 個密碼。</p><h3 id="在基於-rpm-的系統中禁止使用近期使用過的密碼" tabindex="-1">在基於 RPM 的系統中禁止使用近期使用過的密碼 <a class="header-anchor" href="#在基於-rpm-的系統中禁止使用近期使用過的密碼" aria-label="Permalink to “在基於 RPM 的系統中禁止使用近期使用過的密碼”">​</a></h3><p>這點對於 RHEL 6.x 和 RHEL 7.x 和它們的衍生系統 CentOS、Scientific Linux 是相同的。</p><p>以 root 身份編輯 <code>/etc/pam.d/system-auth</code> 文件，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/pam.d/system-auth</span></span></code></pre></div><p>找到下面這行，並且在末尾添加文字 <code>remember=5</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>password     sufficient     pam_unix.so sha512 shadow nullok try_first_pass use_authtok remember=5</span></span></code></pre></div><p>現在你瞭解了 Linux 中的密碼策略，以及如何在基於 DEB 和 RPM 的系統中設置不同的密碼策略。</p><p>就這樣，我很快會在這裏發表另外一天有趣而且有用的文章。在此之前請保持關注。如果您覺得本教程對你有幫助，請在您的社交，專業網絡上分享並支持我們。</p><hr>`,119)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-set-password-policies-in-linux/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-set-password-policies-in-linux/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),a(e,{href:"https://github.com/liujing97"},{default:t(()=>[...s[4]||(s[4]=[i("liujing97",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const C=l(r,[["render",c]]);export{x as __pageData,C as default};
